 if(!room||!me)return <main className="welcome">{graphicsMenu}<div className="welcome-art"><div className="art-sun"/><div className="art-mountain one"/><div className="art-mountain two"/><div className="art-road">〰</div><div className="art-label">MOUNTAIN RUSH<br/>CONQUER ROUTE 1081</div></div><div className="entry"><div className="eyebrow">MOUNTAIN RUSH / ROUTE 1081</div><h1>Mountain Rush<br/><em>ซิ่งเขา 1081</em></h1><p>อ่านทาง เตรียมเบรก แล้วชิงจังหวะแซงแบบเรียลไทม์<br/>เกมแข่งรถบนถนนภูเขา สำหรับ 1–8 คน</p><label>ชื่อผู้เล่น<input value={name} maxLength={20} onChange={e=>setName(e.target.value)}/></label><TrackSelector selection={mapSelection} onChange={setMapSelection}/><label className="watch-choice"><input type="checkbox" checked={watchOnly} onChange={e=>setWatchOnly(e.target.checked)}/>เข้าห้องเป็นผู้ชม (ดูบอท / เพื่อนแข่ง)</label><button className="primary" onClick={create}>สร้างห้องแข่งขัน <span>↗</span></button><div className="public-rooms"><h3>ห้องที่กำลังเปิด</h3>{publicRooms.length?publicRooms.map(r=><button key={r.code} onClick={()=>join(r.code)}><b>{r.code}</b> · {r.phase==='lobby'?'รอเริ่ม':r.phase==='race'?'กำลังแข่ง':'จบแล้ว'} · รถ {r.racers} (บอท {r.bots}) · ผู้ชม {r.viewers}</button>):<small>ยังไม่มีห้อง · สร้างห้องแรกได้เลย</small>}</div><div className="divider">หรือเข้าร่วมห้อง</div><div className="join"><input placeholder="รหัสห้อง" value={code} onChange={e=>setCode(e.target.value.toUpperCase())}/><button onClick={()=>join(code)}>เข้าห้อง →</button></div>{error&&<p className="error">{error}</p>}<small>ต้นแบบนี้ต้องเปิดเซิร์ฟเวอร์ก่อนเล่นร่วมกัน</small></div></main>;
